WITH -- short_routes AS ( -- SELECT DISTINCT src_id, dest_id -- FROM lis.short_route_sds -- WHERE cohort = '2026' -- ), -- Deduped Funnel Steps (1 row per session + route) srp_deduped AS ( SELECT DISTINCT -- channel_exp_info s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, op_id, CASE WHEN is_ac = True THEN 'AC' ELSE 'non-AC' END AS is_ac, doj, CASE WHEN channel_exp_info IS NULL THEN 'null' WHEN contains(channel_exp_info, 'LMB_FILTER_BP:V0') THEN 'V0' WHEN contains(channel_exp_info, 'LMB_FILTER_BP:V1') THEN 'V1' WHEN contains(channel_exp_info, 'LMB_FILTER_BP:V2') THEN 'V2' WHEN contains(channel_exp_info, 'LMB_FILTER_BP:V3') THEN 'V3' WHEN contains(channel_exp_info, 'LMB_FILTER_BP:V4') THEN 'V4' ELSE 'others' END AS exp_Variant, CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi, CAST(HOUR(at_timezone(s.__time, 'Asia/Kolkata')) AS INT) AS day_hour -- CASE WHEN sr.src_id IS NOT NULL THEN 'Short Routes' ELSE 'Long Routes' END AS route_type, -- CASE WHEN __time >= TIMESTAMP '2026-03-17 18:30:00' AND __time < TIMESTAMP '2026-01-06 18:30:00' THEN 'Pre DBS' -- WHEN __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-03-30 18:30:00' THEN 'Post DBS' -- ELSE 'Others' END AS time_period FROM "user_interaction"."search_route_details" s -- LEFT JOIN short_routes sr ON s.src_id = sr.src_id AND s.dest_id = sr.dest_id WHERE s.__time >= TIMESTAMP '2026-03-17 18:30:00' AND s.__time < TIMESTAMP '2026-03-30 18:30:00' AND s.country = 'IND' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND channel_exp_info IS NOT NULL AND CAST(src_id AS VARCHAR) || '-' || CAST(dest_id AS VARCHAR) IN ('462-122', '462-124', '462-130', '462-210', '462-222', '462-237', '462-255', '462-309', '462-311', '462-313', '462-362', '462-445', '462-450', '462-472', '462-473', '462-530', '462-545', '462-551', '462-571', '462-572', '462-574', '462-575', '462-579', '462-580', '462-624', '462-641', '462-646', '462-647', '462-750', '462-792', '462-979', '462-1003', '462-1007', '462-1008', '462-1021', '462-1142', '462-1476', '462-1571', '462-1588', '462-65976', '462-71255', '462-76079', '462-83409', '462-86833', '462-95083', '462-95217', '462-95220', '462-95222') -- AND channel_exp_info LIKE '%RTC_PRICE_SHOCK_REDUCTION_P2%' -- AND op_id IN (10283, 16081, 6392, 15447, 8065, 15129, 7115, 10244, 10823, 15130, 11060, 15499, 11044, 3030, 15443, 16124, 16227, 2020, 16374, 16426, 16580, 16647, 16777, 17012, 16884, 4040, 17137, 17101, 17889, 18115, 18101, 18237, 18491, 19393, 19502, 22837, 22875, 22878, 24978, 25187, 25946, 27000, 26936, 27455, 28011, 29176, 29479, 29391, 29392, 32000, 32272, 32245, 34300, 34400, 33740, 35303, 35268, 33000) -- -- AND op_id IN (33000) -- AND group_id > 0 AND s.os = 'Android' -- AND s.os = 'iOS' -- GROUP BY 1,2,3,4,5,6,7,8,9 ), sl_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-03-17 18:30:00' AND __time < TIMESTAMP '2026-03-30 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), mpax_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-03-17 18:30:00' AND __time < TIMESTAMP '2026-03-30 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), tco_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."create_order_details" WHERE __time >= TIMESTAMP '2026-03-17 18:30:00' AND __time < TIMESTAMP '2026-03-30 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-03-17 18:30:00' AND __time < TIMESTAMP '2026-03-30 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), addpay_deduped AS ( SELECT mri_session_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."make_payment_details" WHERE __time >= TIMESTAMP '2026-03-17 18:30:00' AND __time < TIMESTAMP '2026-03-30 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1 ), confirm_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-03-17 18:30:00' AND __time < TIMESTAMP '2026-03-30 18:30:00' -- AND os = 'Android' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT -- '18 to 30 Mar 2026' AS month_period, CASE WHEN date_diff('day', srp.doi, srp.doj) = 0 AND srp.day_hour >= 17 THEN '0. LMB Same Day' WHEN date_diff('day', srp.doi, srp.doj) = 0 AND srp.day_hour < 17 THEN '0. non-LMB Same Day' WHEN date_diff('day', srp.doi, srp.doj) = 1 THEN '1. DBD 1' WHEN date_diff('day', srp.doi, srp.doj) = 2 THEN '2. DBD 2' WHEN date_diff('day', srp.doi, srp.doj) > 2 THEN '3. DBD 2+' ELSE 'NA' END AS dbd, -- srp.doi, srp.exp_Variant, -- srp.iOS_Variant, UPPER(srp.user_type) as user_type, -- 'Overall' AS user_type, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, -- (CAST(srp.src_id AS VARCHAR) ||'-'|| CAST(srp.dest_id AS VARCHAR)) AS SD_ID, -- (src.location_name || '-' || dest.location_name) AS route, -- srp.route_type, -- srp.is_ac, -- 'Overall' AS is_ac, -- srp.op_id, -- bo.travels rtc, -- '' AS RTC_Cohort, -- CASE WHEN srp.os IS NOT NULL THEN srp.channel ELSE srp.os END AS saleschannel, COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT pax.mri_session_id) AS paxload, -- COUNT(DISTINCT tco.mri_session_id) AS tcoload, COUNT(DISTINCT oi.mri_session_id) AS paymentload, COUNT(DISTINCT ap.mri_session_id) AS addPayClick, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, -- COUNT(DISTINCT srp.rb_user_id) AS srpUsers, -- COUNT(DISTINCT sl.rb_user_id) AS slUsers, -- COUNT(DISTINCT pax.rb_user_id) AS paxUsers, -- COUNT(DISTINCT tco.rb_user_id) AS tcoUsers, -- COUNT(DISTINCT oi.rb_user_id) AS orderinfoUsers, -- COUNT(DISTINCT conf.rb_user_id) AS confirmUsers, SUM(conf.tin_count) AS tin FROM srp_deduped srp -- LEFT JOIN "lis"."config_locations" src ON src.id = srp.src_id -- LEFT JOIN "lis"."config_locations" dest ON dest.id = srp.dest_id -- LEFT JOIN "lis"."operators" bo ON srp.op_id = bo.operator_id LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN tco_deduped tco ON srp.mri_session_id = tco.mri_session_id AND srp.route_id = tco.route_id LEFT JOIN orderinfo_deduped oi ON srp.mri_session_id = oi.mri_session_id AND srp.route_id = oi.route_id LEFT JOIN addpay_deduped ap ON ap.mri_session_id = oi.mri_session_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1,2,3,4 -- ,5,6 ORDER BY 4, 3 DESC, 2
